export const ADVANCED_LEARNING_BLOCKS: AdvancedLearningBlock[] = ADVANCED_LEARNING_BLUEPRINT
  .map((entry) => ({ ...entry, ...advancedBlockContent[entry.id] }));

export const ADVANCED_GATE_A_BLOCKS = ADVANCED_LEARNING_BLOCKS.filter((entry) => GATE_A_IDS.has(entry.id));
export const ADVANCED_GATE_B_BLOCKS = ADVANCED_LEARNING_BLOCKS.filter((entry) => !GATE_A_IDS.has(entry.id));

export const ADVANCED_LEARNING_MANIFEST_IDS = ADVANCED_LEARNING_BLUEPRINT.map((entry) => entry.id);
export const ADVANCED_GATE_A_IDS = ADVANCED_GATE_A_BLOCKS.map((entry) => entry.id);
export const ADVANCED_GATE_B_IDS = ADVANCED_GATE_B_BLOCKS.map((entry) => entry.id);
export const ADVANCED_LESSON_MINUTES = ADVANCED_LEARNING_BLUEPRINT.reduce((total, entry) => total + entry.minutes, 0);
export const ADVANCED_GATE_A_MINUTES = ADVANCED_GATE_A_BLOCKS.reduce((total, entry) => total + entry.minutes, 0);
export const ADVANCED_GATE_B_MINUTES = ADVANCED_GATE_B_BLOCKS.reduce((total, entry) => total + entry.minutes, 0);

if (ADVANCED_LEARNING_BLUEPRINT.length !== 40 || new Set(ADVANCED_LEARNING_MANIFEST_IDS).size !== 40) {
  throw new Error("The Pilot 2 Advanced Learning manifest must contain exactly 40 unique blocks.");
}
if (ADVANCED_LESSON_MINUTES !== 245) throw new Error(`Advanced lesson minutes must total 245; found ${ADVANCED_LESSON_MINUTES}.`);
if (ADVANCED_GATE_A_BLOCKS.length !== 8 || ADVANCED_GATE_A_MINUTES !== 53) {
  throw new Error("Advanced Bridge Gate A must preserve exactly eight accepted representative blocks totalling 53 minutes.");
}
if (ADVANCED_GATE_B_BLOCKS.length !== 32 || ADVANCED_GATE_B_MINUTES !== 192) {
  throw new Error("Advanced Bridge Gate B must add exactly thirty-two blocks totalling 192 minutes.");
}
if (Object.keys(advancedBlockContent).length !== 40 || ADVANCED_LEARNING_BLOCKS.some((block) => !block.connection || block.paragraphs?.length !== 3 || !block.evidence?.columns?.length || !block.evidence?.rows?.length || !block.modelId)) {
  throw new Error("Every Advanced Learning block must have complete authored explanation, evidence, and model-link content.");
}
